import { action, definePlugin, text } from "zero";
import { summarize } from "./summarize";

export default function seo(options: { suffix: string }) {
  return definePlugin({
    name: "seo",
    hooks: {
      posts: {
        beforeCreate(data) {
          // Package TypeScript compiles as checked JavaScript; String() types the value for the row.
          data.summary = String(summarize(data.title)) + String(options.suffix);
        },
      },
    },
    actions: {
      // The URL is built at runtime, so the lock records `*`; the app narrowed it to one host.
      lookup: action({
        input: { url: text().notNull() },
        access: "anyone",
        async handler(input) {
          return (await fetch(input.url)).status;
        },
      }),
    },
  });
}
